steps.script:
# Two user plans: one that breaks the envelope and one that does not, so the
# assertions below have a built-in control. fixture_minimal_valid places a
# single 11-model Gretchin mob 15.00" across; fixture_recon_stomps_rich's
# widest unit is 8.13".
var PV = load("res://scripts/PlanValidator.gd")
var PM = load("res://scripts/PlanManager.gd")
PM.ensure_user_plans_dir()
var dir = DirAccess.open("user://ai_plans")
if dir != null:
	dir.list_dir_begin()
	var f = dir.get_next()
	while f != "":
		if f.ends_with(".json"):
			dir.remove(f)
		f = dir.get_next()
	dir.list_dir_end()
var written = []
for src in ["res://tests/fixtures/ai_plans/fixture_minimal_valid.json", "res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json"]:
	var plan = PV.load_plan_file(src)
	var path = "user://ai_plans/%s.json" % PM.slugify(str(plan.get("name", "")))
	var file = FileAccess.open(path, FileAccess.WRITE)
	file.store_string(JSON.stringify(plan, "\t"))
	file.close()
	written.append(path.get_file())
written.sort()
return ",".join(written)

# The widest pair in each fixture, so the rest of this scenario cannot pass
# on a fixture that quietly changed shape.
var PV = load("res://scripts/PlanValidator.gd")
var out = []
for src in ["res://tests/fixtures/ai_plans/fixture_minimal_valid.json", "res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json"]:
	var plan = PV.load_plan_file(src)
	var worst = 0.0
	for p in plan.get("deployment", {}).get("placements", []):
		var ms = p.get("models_inches", [])
		for i in range(ms.size()):
			for j in range(i + 1, ms.size()):
				var d = Vector2(float(ms[i][0]), float(ms[i][1])).distance_to(Vector2(float(ms[j][0]), float(ms[j][1])))
				worst = max(worst, d)
	out.append("%.2f" % worst)
print("SCENARIO pm_f4 widest pair: minimal=%s rich=%s" % [out[0], out[1]])
return "%s|%s" % [out[0], out[1]]

# The status column the player actually reads, for BOTH rows. Rows are found
# by name — shipped plans sit in this list too and their number is not this
# scenario's business.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var found = {}
var item = t.get_root().get_first_child()
while item != null:
	found[item.get_text(0)] = item.get_text(4)  # COL_STATUS
	item = item.get_next()
var over = str(found.get("Fixture — minimal valid", "MISSING"))
var ok = str(found.get("Fixture — Recon Stomps rich (all five verbs)", "MISSING"))
print("SCENARIO pm_f4 status column: over-spread='%s' well-formed='%s'" % [over, ok])
return "%s|%s" % [over, ok]

# The note is rendered in the warning colour, not the invalid colour — the
# plan is usable, it just will not deploy exactly as drawn.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Fixture — minimal valid":
		var c = item.get_custom_color(4)  # COL_STATUS
		var dlg = node.get_node("/root/MainMenu/PlanBrowserDialog")
		return "warn=%s invalid=%s" % [str(c == dlg.WARN_COLOR), str(c == dlg.INVALID_COLOR)]
	item = item.get_next()
return "row not found"

# Selecting the row must put the sentence in front of the player, naming the
# unit and the rule — a bare count would not tell them what to change.
var dlg = node.get_node("/root/MainMenu/PlanBrowserDialog")
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Fixture — minimal valid":
		item.select(0)
		t.item_selected.emit()
		break
	item = item.get_next()
var txt = str(dlg.detail_label.text)
print("SCENARIO pm_f4 detail panel: %s" % txt)
var names_unit = txt.find("U_GRETCHIN_A") != -1
var names_rule = txt.find("11th-edition unit coherency") != -1
var names_count = txt.find("8 of 11 models") != -1
return "unit=%s rule=%s count=%s" % [str(names_unit), str(names_rule), str(names_count)]

# Still VALID: a note is not a rejection. The consumer repairs the placement
# where it can and otherwise deploys that ONE unit with the formula, so the
# rest of the plan still applies — making this an error would refuse a plan
# that works.
var PV = load("res://scripts/PlanValidator.gd")
var ALM = node.get_node("/root/ArmyListManager")
var army = ALM.load_army_list("recon_stomps", 1)
var plan = PV.load_plan_file("user://ai_plans/fixture_minimal_valid.json")
var r = PV.validate_plan(plan, army)
print("SCENARIO pm_f4 validate: valid=%s errors=%d warnings=%d" % [str(r.get("valid")), r.get("errors", []).size(), r.get("warnings", []).size()])
return "valid=%s errors=%d" % [str(r.get("valid")), r.get("errors", []).size()]

# And nothing that ships carries the note, so the check is not simply firing
# on everything.
var PV = load("res://scripts/PlanValidator.gd")
var ALM = node.get_node("/root/ArmyListManager")
var army = ALM.load_army_list("recon_stomps", 1)
var total = 0
for p in ["res://data/ai_plans/orks_recon_stomps_crucible.json", "res://data/ai_plans/orks_recon_stomps_hammer_anvil.json"]:
	var r = PV.validate_plan(PV.load_plan_file(p), army)
	total += r.get("warnings", []).size() + r.get("errors", []).size()
print("SCENARIO pm_f4 shipped plans: %d errors+warnings across both" % total)
return total
